<?php declare(strict_types=1);use Bulbula\Core\Csrf;use Bulbula\Core\View;$appeals=$appeals??[]; ?>
<section class="b-mod-toolbar"><div class="b-mod-toolbar__title"><strong>Review appeals · <?= count($appeals) ?></strong><span>Administrator-only human reconsideration of rejected and removed Customer reviews.</span></div><a class="b-btn b-btn--outline b-btn--sm" href="/staff/moderation">Initial moderation</a></section>
<?php if($appeals===[]): ?><div class="b-mod-empty"><strong>No review appeals</strong>The appeal queue is clear.</div><?php else: ?><section class="b-mod-list"><?php foreach($appeals as $appeal): ?><article class="b-mod-item"><div><div class="b-mod-item__meta"><span class="b-mod-item__id">Appeal #<?= (int)$appeal['id'] ?></span><span>Review #<?= (int)$appeal['review_id'] ?></span><span><?= View::e($appeal['branch_name_en']) ?></span><span class="b-badge <?= empty($appeal['outcome'])?'b-badge--orange':'b-badge--verified' ?>"><?= View::e($appeal['outcome']??'PENDING') ?></span></div><p class="b-mod-item__review"><?= View::e($appeal['review_text']??'(Rating only)') ?></p><p><strong>Original decision:</strong> <?= View::e(str_replace('_',' ',(string)$appeal['original_status'])) ?> · <?= View::e(str_replace('_',' ',(string)($appeal['original_reason_code']??''))) ?> by <?= View::e($appeal['original_moderator_name']??'Staff') ?></p><p><strong>Customer context:</strong> <?= View::e($appeal['appeal_statement']) ?></p><?php if(!empty($appeal['decision_notes'])): ?><p><strong>Final explanation:</strong> <?= View::e($appeal['decision_notes']) ?></p><?php endif; ?></div><?php if(empty($appeal['outcome'])): ?><form method="POST" action="/staff/review-appeals/<?= (int)$appeal['id'] ?>/decide" class="b-mod-actions"><?= Csrf::field() ?><select class="b-select" name="outcome" required><option value="">Final outcome</option><option value="OVERTURNED">Overturn and publish</option><option value="UPHELD">Uphold decision</option></select><select class="b-select" name="reason_code" required><option value="">Decision basis</option><option value="CONTEXT_CHANGED_DECISION">Additional context changed decision</option><option value="ORIGINAL_DECISION_CORRECT">Original policy decision correct</option><option value="INSUFFICIENT_NEW_EVIDENCE">Insufficient new evidence</option></select><textarea class="b-input" name="decision_notes" minlength="10" maxlength="2000" required placeholder="Explain the final decision to the Customer"></textarea><button class="b-btn b-btn--primary b-btn--sm">Record final decision</button></form><?php endif; ?></article><?php endforeach; ?></section><?php endif; ?>
